create extension if not exists btree_gist;
create schema s13;
create table s13.t (
  id bigint generated by default as identity (sequence name s13.custom_id_seq start with 5 increment by 2),
  room int,
  during tstzrange,
  code text,
  extra text,
  constraint t_pk primary key (id) include (code) with (fillfactor = 80),
  constraint t_code_uq unique (code) include (extra) with (fillfactor = 70),
  constraint t_no_overlap exclude using gist (room with =, during with &&) include (code) where (room > 0)
);
create table s13.u (id int primary key using index tablespace pg_default, v int);
alter table s13.u add constraint u_v_uq unique nulls not distinct (v) deferrable initially deferred;
